import{_ as t,o as u,c as e,ag as q}from"./chunks/framework.B5ULsuav.js";const k=JSON.parse('{"title":"中论丹道金句","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/quote-中论丹道.md","filePath":"40-原话金句/quote-中论丹道.md","lastUpdated":1778155802000}'),r={name:"40-原话金句/quote-中论丹道.md"};function a(l,o,c,n,s,b){return u(),e("div",null,[...o[0]||(o[0]=[q('<h1 id="中论丹道金句" tabindex="-1">中论丹道金句 <a class="header-anchor" href="#中论丹道金句" aria-label="Permalink to &quot;中论丹道金句&quot;">​</a></h1><blockquote><p>了空居士《中论丹道》精彩原话集</p></blockquote><hr><h2 id="一、丹道总纲" tabindex="-1">一、丹道总纲 <a class="header-anchor" href="#一、丹道总纲" aria-label="Permalink to &quot;一、丹道总纲&quot;">​</a></h2><blockquote><p><strong>&quot;中论丹道——中就是中道，不偏不倚；论就是论述、讨论；丹道就是金丹大道。合起来就是用中道的智慧来修金丹大道。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;性命双修——既要明心（性功），也要修身（命功）。心不明则行不正，身不修则气不畅。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;修丹就是修心，炼气就是炼意。心平气和，丹道自成。&quot;</strong></p></blockquote><hr><h2 id="二、似守非守——火候真诀" tabindex="-1">二、似守非守——火候真诀 <a class="header-anchor" href="#二、似守非守——火候真诀" aria-label="Permalink to &quot;二、似守非守——火候真诀&quot;">​</a></h2><blockquote><p><strong>&quot;不可用心守，不可无意求。守得太紧就着相，守得太松就无效。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;似守非守——轻轻知道，轻轻放下。在有心无心之间。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;火候的窍诀：心平气和就是火候。不要刻意调控，心平气和了，一切自自然然。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;但安神息，不运火而火自运——只要你心平气和，身体的气机就自然运行。不需要你去&#39;指挥&#39;它。&quot;</strong></p></blockquote><hr><h2 id="三、静坐要旨" tabindex="-1">三、静坐要旨 <a class="header-anchor" href="#三、静坐要旨" aria-label="Permalink to &quot;三、静坐要旨&quot;">​</a></h2><blockquote><p><strong>&quot;静坐最重要的是姿势中正安舒，不要硬撑。双盘、单盘、散盘、坐椅子都可以。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;静坐时杂念来了，看着它，不跟随，不攀缘，它自然就消失了。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;走神了——让走神，知道走神就不走神。不要和杂念打架，它来了就让它来，知道了它就走了。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;静坐时轻轻返观整个体腔——膻中到丹田这一片区域，似守非守。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;不要追求感觉。有感觉是正常的，没感觉也是正常的。感觉是副产品。&quot;</strong></p></blockquote><hr><h2 id="四、功夫层次" tabindex="-1">四、功夫层次 <a class="header-anchor" href="#四、功夫层次" aria-label="Permalink to &quot;四、功夫层次&quot;">​</a></h2><blockquote><p><strong>&quot;百日功灵，必有变化——坚持一百天，身体一定会有变化。十月胎圆，功夫更深。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;行住坐卧，绵绵若存——不是只有打坐时才观照，而是走路、站着、坐着、躺着，随时保持一种轻轻返观身体的状态。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;神守黄房，金胎自成——黄房就是中丹田，轻轻观照中丹田，丹道的基础就自然形成了。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;抱元守一——先天的元神和元炁，不是割裂的，而是一体的。修炼到深处，神中有气，气中有神，分不开。&quot;</strong></p></blockquote><hr><h2 id="五、修行误区" tabindex="-1">五、修行误区 <a class="header-anchor" href="#五、修行误区" aria-label="Permalink to &quot;五、修行误区&quot;">​</a></h2><blockquote><p><strong>&quot;有些人以为打坐就是要&#39;入静&#39;，拼命压念头，越压越烦躁。其实有杂念是正常的，关键是你知不知道它有。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;修行不是把自己变成一个没有感情的人。该哭哭，该笑笑，只是不被情绪牵着走。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;最清净的人就是死人。第二清净的人就是老人痴呆症。修行人不是追求这种清净。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;不要想着&#39;修成了再去做&#39;。你修行了，就是。不是先修好再得，是当下即是。&quot;</strong></p></blockquote><hr><h2 id="六、融会贯通" tabindex="-1">六、融会贯通 <a class="header-anchor" href="#六、融会贯通" aria-label="Permalink to &quot;六、融会贯通&quot;">​</a></h2><blockquote><p><strong>&quot;《中论丹道》是融合了禅、净、密、道四家的实修方法。万法归宗，最终目的都是明心见性。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;我这么说，不是让你们迷信我。我的每一句话你都可以去验证——实践是检验真理的唯一标准。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;修行就是最简单的事——与人为善，观察自己的念头。做到这两点，一切都在其中。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;愿力决定层次，魄力决定成就——你的愿有多大，你的功夫就能走多远。&quot;</strong></p></blockquote><hr><h2 id="七、简短金句" tabindex="-1">七、简短金句 <a class="header-anchor" href="#七、简短金句" aria-label="Permalink to &quot;七、简短金句&quot;">​</a></h2><blockquote><p>&quot;似守非守。&quot;</p></blockquote><blockquote><p>&quot;心平气和。&quot;</p></blockquote><blockquote><p>&quot;百日功灵。&quot;</p></blockquote><blockquote><p>&quot;绵绵若存。&quot;</p></blockquote><blockquote><p>&quot;了即业障本空。&quot;</p></blockquote><hr><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/中论丹道_了空居士_完整版(全83篇)">中论丹道_了空居士_完整版(全83篇)</a> 整理日期：2026-05-06</p></blockquote>',47)])])}const h=t(r,[["render",a]]);export{k as __pageData,h as default};
